import importlib.util, sys
from pathlib import Path

# Load QA test module
mod_path = Path('qa_instances_eval/python-control/bdalg_append_dispatch_diversity_subset_suite/files/tests/qa/bdalg_append_dispatch_diversity_subset_suite_test.py')
spec = importlib.util.spec_from_file_location('qa_mod', mod_path)
qa_mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(qa_mod)

# Candidate concrete append functions by qualified name
candidates = {
    'control.xferfcn.append',
    'control.statesp.append',
    'control.frdata.append',
}

active_depth = 0
seen = set()

def profiler(frame, event, arg):
    global active_depth
    if event not in ('call', 'return', 'exception'):
        return profiler
    name = frame.f_code.co_name
    mod = frame.f_globals.get('__name__', '')
    qual = f"{mod}.{name}"

    if event == 'call':
        if qual == 'control.bdalg.append':
            active_depth += 1
        elif active_depth > 0 and qual in candidates:
            seen.add((frame.f_code.co_filename, qual))

    elif event in ('return', 'exception'):
        if qual == 'control.bdalg.append' and active_depth > 0:
            active_depth -= 1
    return profiler

sys.setprofile(profiler)
try:
    # Execute all tests manually
    for name, obj in vars(qa_mod).items():
        if isinstance(obj, type) and name.startswith('Test'):
            inst = obj()
            for meth_name in dir(inst):
                if meth_name.startswith('test_'):
                    getattr(inst, meth_name)()
finally:
    sys.setprofile(None)

print('SEEN_START')
for fn, qual in sorted(seen):
    print(fn, '::', qual)
print('SEEN_END')
